attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU; vec3 arcAt(vec3 a, vec3 b, float f){ return mix(a, b, f); }
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/18.0;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(arcAt(aO, aE, u/tt), 1.); float S = .32;
      float c = cos(u*6.), s = sin(u*6.); vec2 q = mat2(c, -s, s, c)*position.xy;       // corona churns
      mv.xy += q*S*1.2; vP = position.xy; vU = u; gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    void main(){                                              // astral star: 4 long points + 4 short, bright core, soft halo
      vec2 p = vP; float r = length(p), a = atan(p.y, p.x);
      float d = abs(p.x)*2.2 + abs(p.y)*.9 - .55;                             // tall sharp crystal
      float edge = exp(-pow(d/.05, 2.)), fill = smoothstep(.04, -.12, d)*.35, facet = exp(-pow(p.x/.025, 2.))*smoothstep(.1, -.3, d)*.6;
      float halo = exp(-r*r*7.)*.18;
      vec3 o = (uOrange*(edge*.9 + fill + halo) + mix(uGold, vec3(1.), .5)*(facet + edge*.3))*smoothstep(1., .85, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

