      if (u < 0. || u > tt + .2){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = (aE - aO)/L;
      float head = min(u*18.0, L), tail = max(0., head - .7) + max(0., u - tt)/.2*1.7;   // after the hit, the tail catches up
      if (head - tail < .01){ gl_Position = vec4(2.,2.,2.,1.); return; }
